using System.Collections;using System.Linq;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;using LegendsOfRus.GameplayCore;
namespace LegendsOfRus.Tests.CampaignPlayMode {
public class MechanicsInteractionPlayModeTests {
 GameObject root; MechanicsSandbox Open(){root=new GameObject("InteractionR12",typeof(RectTransform),typeof(Canvas));return MechanicsSandbox.Open((RectTransform)root.transform,()=>{},true);}
 [UnityTearDown] public IEnumerator Cleanup(){if(root)Object.Destroy(root);yield return null;}
 static BoardSnapshot Start(SpecialGemKind kind){var b=new BoardModel(8,7,6,new SeededBoardRandom(1));for(int y=0;y<7;y++)for(int x=0;x<8;x++)b.SetCell(new BoardPosition(x,y),new BoardCellData((x+2*y)%5));b.SetCell(new BoardPosition(3,3),new BoardCellData(5,kind));return b.CreateSnapshot();}
 static IEnumerator Settle(Match3Board board){float end=Time.realtimeSinceStartup+25;while(board.HasActiveCommand&&Time.realtimeSinceStartup<end)yield return null;Assert.That(board.HasActiveCommand,Is.False);}
 [UnityTest] public IEnumerator DefaultRoundAndAllSpecialDragsUseNewRules(){var s=Open();yield return null;Assert.That(s.Rules,Is.EqualTo(GameplayRuleVersion.PrototypeR4));Assert.That(s.Board.RuleVersion,Is.EqualTo(GameplayRuleVersion.PrototypeR4));Assert.That(s.AttemptLog.ToJson(),Does.Contain("RulesR4"));
 foreach(var kind in new[]{SpecialGemKind.Row,SpecialGemKind.Column,SpecialGemKind.Burst,SpecialGemKind.Spark,SpecialGemKind.Color}){s.Reset(0,GameplayRuleVersion.PrototypeR4);yield return null;Assert.That(s.Board.LoadSnapshotForTesting(Start(kind)),Is.True);int before=s.Board.Moves;MechanicsSandboxPlayModeTests.Capture(root,"InteractionR12_"+kind+"_Before",576,1280);Assert.That(s.Board.SwipeCell(3,3,Vector2Int.right),Is.True);yield return Settle(s.Board);Assert.That(s.Board.LastMechanicsCommand.Rules,Is.EqualTo(GameplayRuleVersion.PrototypeR4));Assert.That(s.Board.BoardStateHash,Is.EqualTo(s.Board.LastMechanicsCommand.Resolve().FinalSnapshot.StateHash));Assert.That(s.Board.Moves,Is.EqualTo(before-1));Assert.That(s.Board.CanAcceptPointerInput,Is.True);MechanicsSandboxPlayModeTests.Capture(root,"InteractionR12_"+kind+"_After",576,1280);}}
 [UnityTest] public IEnumerator RainbowCombinationUsesVisibleOrdinaryMajority(){var s=Open();s.Reset(0,GameplayRuleVersion.PrototypeR4);yield return null;var snap=Start(SpecialGemKind.Color);var b=new BoardModel(8,7,6,new SeededBoardRandom(1));b.RestoreSnapshot(snap);b.SetCell(new BoardPosition(4,3),new BoardCellData(5,SpecialGemKind.Row));s.Board.LoadSnapshotForTesting(b.CreateSnapshot());MechanicsSandboxPlayModeTests.Capture(root,"InteractionR12_RainbowCombo_Before",576,1280);Assert.That(s.Board.SwipeCell(3,3,Vector2Int.right),Is.True);yield return Settle(s.Board);var p=s.Board.LastMechanicsCommand.Resolve();var converted=p.Waves[0].Activations.Where(a=>a.Kind==SpecialGemKind.Row&&a.ForcedByCombination).ToArray();Assert.That(converted,Is.Not.Empty);Assert.That(converted.All(a=>a.TileType==2),Is.True);Assert.That(s.Board.BoardStateHash,Is.EqualTo(p.FinalSnapshot.StateHash));MechanicsSandboxPlayModeTests.Capture(root,"InteractionR12_RainbowCombo_After",576,1280);}
 [UnityTest] public IEnumerator LegacyFixtureSelectionAndNewRoundRetryStaySeparate(){var s=Open();yield return null;string start=s.Board.BoardStateHash;int moves=s.Board.Moves;s.Reset(0,GameplayRuleVersion.PrototypeR3);yield return null;Assert.That(s.Board.RuleVersion,Is.EqualTo(GameplayRuleVersion.PrototypeR3));s.Reset(0,GameplayRuleVersion.Legacy);yield return null;Assert.That(s.Board.RuleVersion,Is.EqualTo(GameplayRuleVersion.Legacy));s.OpenRound(0);yield return null;Assert.That(s.Board.RuleVersion,Is.EqualTo(GameplayRuleVersion.PrototypeR4));Assert.That(s.Board.BoardStateHash,Is.EqualTo(start));Assert.That(s.Board.Moves,Is.EqualTo(moves));}
}}
